function pageviews(e){if(!e||"object"!=typeof e)throw new TypeError("pageviews(): options must be an object.");const{start_views:t,start_date:r,coefficient:i}=e;if(!Number.isInteger(t)||t<=0)throw new TypeError("pageviews(): start_views must be an integer greater than zero.");if(!(r instanceof Date)||Number.isNaN(r.getTime()))throw new TypeError("pageviews(): start_date must be a valid Date object.");const a=new Date;if(r.getTime()>a.getTime())throw new RangeError("pageviews(): start_date cannot be in the future.");if(!Number.isFinite(i)||i<=0)throw new TypeError("pageviews(): coefficient must be a number greater than zero.");const o=a.getTime()-r.getTime(),n=Math.floor(o/864e5);return Math.floor(t+i*Math.pow(n,1.1))}window.pageviews=pageviews;